using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketClassifierService>();

var app = builder.Build();

// Train the model at startup and register the prediction engine pool
var trainer = app.Services.GetRequiredService<TicketClassifierService>();
trainer.TrainAndSave();

builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(trainer.GetModelPath());

// Rebuild the app with the prediction pool registered
app = builder.Build();
app.MapControllers();
app.Run();

